import{_ as a,a0 as r,w as O,s,ao as n,I as l,x as t,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"為什麼公司需要設立開源項目辦公室 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼公司需要設立開源項目辦公室 | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼公司需要設立開源項目辦公室 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼公司需要設立開源項目辦公室 | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20220826 Why Companies Need to Set Up an Open Source Program Office","title":"為什麼公司需要設立開源項目辦公室","tag":"202311","desc":""},"relativePath":"202311/20220826 Why Companies Need to Set Up an Open Source Program Office.md","filePath":"[post].md"}'),S={name:"202311/20220826 Why Companies Need to Set Up an Open Source Program Office.md"};function u(P,e,d,m,f,h){const o=r("Link");return O(),s("div",null,[e[15]||(e[15]=n('<h1 id="為什麼公司需要設立開源項目辦公室" tabindex="-1">為什麼公司需要設立開源項目辦公室 <a class="header-anchor" href="#為什麼公司需要設立開源項目辦公室" aria-label="Permalink to “為什麼公司需要設立開源項目辦公室”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202311/01/232800a8c8bk3b83rtbn6x.jpg" alt=""></p><blockquote><p>要想軟件產品能夠成功，關鍵在於管理開源軟件的使用並降低合規風險。開源項目辦公室能幫助組織實現這一目標。讓我們一起深入瞭解。</p></blockquote><p><ruby>開源軟件<rt>Open source software</rt></ruby>（OSS）是構建現代軟件解決方案的重要組成部分。無論是服務於內部或是面向客户的解決方案，如今的組織都在很大程度上依賴於開源軟件。開源軟件組件受其獨立的授權條款約束，對這些條款的不合規操作往往會使組織面臨安全和知識產權（IP）風險，這進而可能會損害公司的品牌價值。</p><p>當開發團隊正忙於發佈軟件版本時，他們的主要目標是滿足項目的截止日期。因此，他們在跟蹤組件版本、庫或者引入項目的第三方代碼時，往往疏於應有的嚴格性。這意味着帶有許可限制或漏洞的開源軟件組件可能會進入代碼庫，然後交付給客户，這對客户和提供軟件解決方案的公司都將帶來風險。</p><p>開發人員為開源項目做出貢獻的領域也日益具有挑戰性。如果公司能夠參與，他們可以獲得多種益處，包括保持技能的最新性，挽留員工，吸引開發者為組織工作，以及提升公司形象。很多開源項目要求開發者簽署貢獻者許可協議，該協議聲明由開發者創建的知識產權屬於該項目，而非開發者本人。在這種情況下，組織需要確保那些不公開源代碼的知識產權和商業機密不會被轉讓給開源項目。</p><p>我們需要教育開發者去了解開源許可的相關問題，確定何時、如何以及在何種程度上向社區提供支持，以及哪些軟件包可能會給組織的聲譽帶來風險。通過制定一套戰略性的政策和操作流程，我們可以規範這一切。實現上述目標的一種方式就是設立一個專門處理所有開源相關事務的部門——即 <ruby>開源項目辦公室<rt>open source program office</rt></ruby>（OSPO）。</p><p>OSPO 為員工使用開源軟件創建了一個生態環境，使合規風險得到良好的控制。OSPO 的角色不僅在於監督開源軟件的使用，它還負責回饋社區，並通過積極參與各種活動以及組織網絡研討會和促銷活動，來推動公司在市場上的增長。</p><p>在這篇文章裏，我們將深入探討為何公司需要設立一個 OSPO，以及它是如何在開源政策和管理程序中嶄露頭角的。</p><h3 id="為何我們需要一個開源項目辦公室-ospo" tabindex="-1">為何我們需要一個開源項目辦公室（OSPO）？ <a class="header-anchor" href="#為何我們需要一個開源項目辦公室-ospo" aria-label="Permalink to “為何我們需要一個開源項目辦公室（OSPO）？”">​</a></h3><p>由於開源軟件正廣泛地被運用，因此在產品開發週期中，為團隊對其使用的監管和維持合規性策略往往會帶來重大壓力。</p><p>開發者往往會忽略許可證責任，有時甚至管理層或各利益相關方也並未完全意識到不遵守這些開源許可證的影響。不論是用於內部還是外部目的，OSPO 能處理從開始引入開源軟件，直至交付給終端用户的過程中的所有環節。</p><p>通過在軟件開發生命週期早期階段開始進行合規性和規章制度的檢查，OSPO 能構築堅實的基礎。這通常開始於引導和整合團隊成員，共同邁向一個能惠及組織價值觀的方向。OSPO 會設定關於開源使用的政策和流程，並在公司內部進行角色和職責的管理。</p><p>總結來説，OSPO 有助於整合所有參與產品構建的相關團隊的努力，進而提升組織更好和更有效使用開源的能力。</p><h4 id="開源項目辦公室-ospo-的崛起" tabindex="-1">開源項目辦公室（OSPO）的崛起 <a class="header-anchor" href="#開源項目辦公室-ospo-的崛起" aria-label="Permalink to “開源項目辦公室（OSPO）的崛起”">​</a></h4><p>諸如微軟、谷歌和 Netflix 等公司已經在自身組織內部設立了成熟的 OSPO。此外，像 Porsche 和 Spotify 這樣的公司也在建立自己的 OSPO，以實現開源的高效利用。</p><p>以下是一些知名公司的領導者對 OSPO 實踐的看法：</p><ul><li>“對於公司來説，這是一種文化的變遷，”Jeff McAffer 解釋了他的觀點，他曾經多年負責微軟的 OSPO，並現在是 GitHub 的產品主管，致力於在企業界推動開源的發展。“很多公司並不習慣與外部團隊合作。”</li><li>“工程、業務、法律每一方的利益相關者都有他們各自的目標和角色，往往需要在速度、質量和風險之間做出權衡，” Spotify 的開源主管 Remy DeCausemaker 解釋道。“ OSPO 的任務就是協調和連接這些單獨的目標，融合成一個能夠減少摩擦的全面策略。”</li><li>Verizon Media 的 OSPO 領導 Gil Yahuda 表達了他的觀點，“我們正在尋找創造一個人才願意融入其中的工作環境。我們的工程師都知道，他們處在一個歡迎開源的環境中，他們在這裏被鼓勵與他們工作相關的開源社區合作。”</li></ul><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/07/Figure-1-OSPO-prevalence-by-industry-2018-2021-2.jpg" alt="圖 1：2018-2021年各行業開源項目辦公室的普及情況 （來源：https://github.com/todogroup/osposurvey/tree/master/2021）"></p><h3 id="開源項目辦公室-ospo-的職能" tabindex="-1">開源項目辦公室（OSPO）的職能 <a class="header-anchor" href="#開源項目辦公室-ospo-的職能" aria-label="Permalink to “開源項目辦公室（OSPO）的職能”">​</a></h3><p>OSPO 的職能可能會根據組織的員工數量、OSPO 團隊的人數以及開源的運用目的不同而有所差異。組織可能只想利用開源軟件來開發產品，也可能同時計劃向社區做出貢獻。</p><p>OSPO 的角色可能會包括評估哪些開源許可證是適宜的，以及是否應讓全職員工參與開源項目等任務。為願意貢獻的開發人員制定貢獻者許可協議（CLA），並確定哪些開源組件有助於產品的快速成長和質量提升也是 OSPO 的重要職責。</p><p>OSPO 的主要職能包括但不限於：</p><ul><li>建立開源合規和治理政策來降低組織的知識產權風險</li><li>培育開發者做出更佳決策的能力</li><li>制定政策規範與公司全面採用開源的工作。</li><li>監控組織內外開源軟件的使用情況</li><li>在每次軟件版本發佈後組織會議，討論開源軟件合規流程的優點及改進空間</li><li>加快軟件開發生命週期（SDLC）</li><li>提高不同部門之間的透明度和協調性</li><li>通過簡化流程在早期階段降低風險</li><li>鼓勵團隊成員向上遊貢獻，以享受開源項目的協作和創新優勢</li><li>提供包含合適補救措施和產品團隊建議的報告</li><li>準備合規文檔，確保滿足許可證的義務</li></ul><h3 id="構建開源項目辦公室-ospo-的過程" tabindex="-1">構建開源項目辦公室（OSPO）的過程 <a class="header-anchor" href="#構建開源項目辦公室-ospo-的過程" aria-label="Permalink to “構建開源項目辦公室（OSPO）的過程”">​</a></h3><p>OSPO 的組成通常包括公司內多個部門的人員。這個過程涉及了對相關部門進行開源合規基礎和使用風險的培訓與教育。OSPO 可能提供法律和技術支持，以確保達成開源的目標需求。</p><p>組織內的 OSPO 可能包括以下人員（這只是一個可能參與的人員名單，並不是詳盡無遺的清單）：</p><ul><li>主任/首席：主任或首席通常是 OSPO 的主要負責人。他能全方位掌控使用開源的各個方面，包括使用不同組件的影響，許可證的含義，以及開發和社區貢獻等。這些要求完全取決於公司的需求。</li><li>項目經理：項目經理為目標解決方案設置需求和目標。他/她將與產品和工程團隊共同工作，以協調工作流程。這包括以開發者友好的方式確保策略和工具的實施。</li><li>法律支持：法律支持可能來自公司外部或者內部，但他們在 OSPO 中扮演着重要角色。法律團隊將與項目經理密切合作，定義管理開源軟件使用的策略，包括每個產品允許使用的開源許可證，如何（或是否）向現有的開源項目貢獻等。</li><li>產品和工程團隊/開發者：工程團隊需要熟悉開源許可及其相關風險。團隊在使用任何開源組件之前，必須得到 OSPO 的批准。團隊可能需要定期接受關於開源合規基礎以及其使用的培訓。</li><li>首席技術官/信息官/利益相關者：公司的領導對 OSPO 策略有着巨大影響。利益相關者在任何產品解決方案的決策過程中擁有很大的決定權。因此，工程副總裁，首席技術官/信息官，或者首席合規/風險官員需要參與 OSPO 的工作。</li><li>IT 團隊：來自 IT 部門的支持十分重要。OSPO 可能被分配實施內部工具的任務，如提高開發者效率，監控開源合規，或者設置開源安全措施等。IT 團隊在協助連接工作流程和確保以開發者友好的方式實施策略方面起着關鍵作用。</li></ul><p>在 TODO 組織於 2021 年執行的 OSPO 調查中，得出了以下的關鍵發現：</p><ul><li>教育企業理解 OSPO 如何為他們帶來益處的機會仍然巨大。</li><li>OSPO 對其贊助方的軟件實踐有顯著的積極影響，但影響的具體效果並因組織規模的大小而異。</li><li>那些有意設立 OSPO 的公司，他們期望 OSPO 能提升創新，但策略設立及預算力度仍然是實現目標的主要挑戰。</li><li>調查參與者中近半數尚未設立 OSPO 的人認為 OSPO 將有助於他們公司的發展，然而在那些認為 OSPO 無助於公司發展的人羣中，有 35% 的人還未對此事有所考慮。</li><li>27% 的調查參與者表示，一家公司對開源參與的程度會深刻影響他們組織的購買決策。</li></ul><p>如今，在構建任何軟件解決方案時，對開源軟件的依賴幾乎是無法避免的。然而，開源許可證相關的潛在風險也不容忽視。因此，我們需要一套策略性的流程來有效解決使用開源組件帶來的合規性問題。</p><p>通過建立一支集中的專業團隊，OSPO 能幫助公司確立規範的開源文化，讓員工瞭解並熟悉與組織內開源使用相關的所有事宜。此外，OSPO 還可以發揮引導作用，吸納行業內的頂級人才，這無疑將對實現商業目標產生積極影響。</p><p><em>（題圖：MJ/9a3e106d-0710-4dd7-b278-ef1056c5c5ab）</em></p><hr>',34)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),i(o,{href:"https://www.opensourceforu.com/2022/08/why-companies-need-to-set-up-an-open-source-program-office/"},{default:p(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/08/why-companies-need-to-set-up-an-open-source-program-office/",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=t("作者：",-1)),i(o,{href:"https://www.opensourceforu.com/author/sakshi-sharma/"},{default:p(()=>[...e[2]||(e[2]=[t("Sakshi Sharma",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),i(o,{href:"https://github.com/lkxed"},{default:p(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),i(o,{href:"https://linux.cn/lctt/ChatGPT"},{default:p(()=>[...e[4]||(e[4]=[t("ChatGPT",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:p(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=a(S,[["render",u]]);export{C as __pageData,x as default};
